import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import Playlist from './components/Playlist';
import Player from './components/Player';
import Library from './components/Library';
import SongDetailWindow from './components/SongDetailWindow';
import songsData from './data/songs';

function App() {
  const [songs, setSongs] = useState(songsData);
  const [filteredSongs, setFilteredSongs] = useState(songsData);
  const [currentSong, setCurrentSong] = useState(songsData[0]);
  const [isPlaying, setIsPlaying] = useState(false);
  const [librarySongs, setLibrarySongs] = useState([]);
  const [currentView, setCurrentView] = useState('playlist');
  const [detailSong, setDetailSong] = useState(null);

  const handleSongSelect = (song) => {
    setCurrentSong(song);
    setIsPlaying(true);
  };

  const handleSearch = (searchTerm) => {
    if (!searchTerm) {
      setFilteredSongs(songs);
    } else {
      const filtered = songs.filter((song) =>
        song.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        song.artist.toLowerCase().includes(searchTerm.toLowerCase()) ||
        song.album.toLowerCase().includes(searchTerm.toLowerCase())
      );
      setFilteredSongs(filtered);
    }
  };

  const handleNext = () => {
    const currentIndex = filteredSongs.findIndex((song) => song.id === (detailSong ? detailSong.id : currentSong.id));
    const nextIndex = (currentIndex + 1) % filteredSongs.length;
    const nextSong = filteredSongs[nextIndex];
    if (detailSong) {
      setDetailSong(nextSong);
    } else {
      setCurrentSong(nextSong);
      setIsPlaying(true);
    }
  };

  const handlePrev = () => {
    const currentIndex = filteredSongs.findIndex((song) => song.id === (detailSong ? detailSong.id : currentSong.id));
    const prevIndex = (currentIndex - 1 + filteredSongs.length) % filteredSongs.length;
    const prevSong = filteredSongs[prevIndex];
    if (detailSong) {
      setDetailSong(prevSong);
    } else {
      setCurrentSong(prevSong);
      setIsPlaying(true);
    }
  };

  const handleAddToLibrary = (song) => {
    if (!librarySongs.find((s) => s.id === song.id)) {
      setLibrarySongs([...librarySongs, song]);
    }
  };

  const handleRemoveFromLibrary = (songId) => {
    setLibrarySongs(librarySongs.filter((song) => song.id !== songId));
  };

  const handleViewChange = (view) => {
    setCurrentView(view);
  };

  const openDetailWindow = (song) => {
    setDetailSong(song);
  };

  const closeDetailWindow = () => {
    setDetailSong(null);
  };

  useEffect(() => {
    setFilteredSongs(songs);
  }, [songs]);

  return (
    <div className="app">
      <Header />
      <div className="main-content">
        <Sidebar onSearch={handleSearch} onViewChange={handleViewChange} currentView={currentView} />
        <div className="right-column">
          {currentView === 'playlist' ? (
            <Playlist
              songs={filteredSongs}
              onSongSelect={handleSongSelect}
              currentSong={currentSong}
              onAddToLibrary={handleAddToLibrary}
              onOpenDetail={openDetailWindow}
            />
          ) : (
            <Library
              librarySongs={librarySongs}
              onSongSelect={handleSongSelect}
              currentSong={currentSong}
              onRemove={handleRemoveFromLibrary}
              onOpenDetail={openDetailWindow}
            />
          )}
          <Player
            song={currentSong}
            isPlaying={isPlaying}
            setIsPlaying={setIsPlaying}
            onNext={handleNext}
            onPrev={handlePrev}
          />
        </div>
      </div>
      {detailSong && (
        <SongDetailWindow
          song={detailSong}
          onClose={closeDetailWindow}
          onNext={handleNext}
          onPrev={handlePrev}
        />
      )}
    </div>
  );
}

export default App;
